	private static void assertNowStepsShareOneDemandedCapture(String kind, boolean freshCapturerFunction) {
		CapturingValues capturer = new CapturingValues();
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal(VF.createLiteral("query time"), null);
		if (!kind.equals("minimal")) {
			context = new ArrayBindingBasedQueryEvaluationContext(context, new String[] { "first" }, null);
		}
		if (kind.equals("planning")) {
			context = AdaptiveFilterEvaluationStep.planningContext(new SingletonSet(), context);
		}
		DefaultEvaluationStrategy strategy = strategy(capturer, freshCapturerFunction);
		QueryValueEvaluationStep first = strategy.precompile(new FunctionCall("NOW"), context);
		QueryValueEvaluationStep second = strategy.precompile(new FunctionCall("NOW"), context);
		assertEquals(0, capturer.captures, "precompilation must not eagerly capture a scalar result");
		Value firstValue = first.evaluate(EmptyBindingSet.getInstance());
		assertSame(firstValue, second.evaluate(EmptyBindingSet.getInstance()));
		assertEquals(1, capturer.captures);
	}

