	@Test
	void concurrentNowCallersShareOneCapturedLiteral() throws Exception {
		CapturingValues capturer = new CapturingValues();
		ValueCapturingQueryEvaluationContext context = new ValueCapturingQueryEvaluationContext(
				new QueryEvaluationContext.Minimal(VF.createLiteral("query time"), null), capturer);
		CountDownLatch start = new CountDownLatch(1);
		try (ExecutorService executor = Executors.newFixedThreadPool(8)) {
			List<Future<Literal>> calls = new ArrayList<>();
			for (int i = 0; i < 8; i++) {
				calls.add(executor.submit(() -> {
					start.await();
					return context.getNow();
				}));
			}
			start.countDown();
			Literal now = calls.get(0).get(5, TimeUnit.SECONDS);
			for (Future<Literal> call : calls) {
				assertSame(now, call.get(5, TimeUnit.SECONDS));
			}
		}
		assertEquals(1, capturer.captures);
	}

