	@Test
	void mutableRowValueAlsoUsedAsQueryConstantIsRecapturedAfterMutation() {
		MutableLiteral input = new MutableLiteral("before");
		CapturingValues capturer = new CapturingValues();
		ValueCapturingQueryEvaluationContext context = new ValueCapturingQueryEvaluationContext(
				new QueryEvaluationContext.Minimal(VF.createLiteral("query time"), null), capturer);
		QueryValueEvaluationStep constant = strategy(capturer).precompile(new ValueConstant(input), context);
		Value constantValue = constant.evaluate(EmptyBindingSet.getInstance());
		MutableBindingSet bindings = context.createBindingSet();
		context.setBinding("first").accept(input, bindings);
		input.replaceLabel("after");
		context.addBinding("second").accept(input, bindings);

		assertEquals("before", bindings.getValue("first").stringValue());
		assertEquals("after", bindings.getValue("second").stringValue(),
				"produced row values must be recaptured even when that caller object also appears in the query model");
		assertEquals("before", constantValue.stringValue(), "the separately captured constant remains immutable");
	}

