	private static final class CapturingValues implements Function<Value, Value> {
		private final Set<Value> owned = Collections.newSetFromMap(new IdentityHashMap<>());
		private int captures;

		@Override
		public synchronized Value apply(Value value) {
			if (owned.contains(value)) {
				return value;
			}
			Literal literal = (Literal) value;
			Literal copy = VF.createLiteral(literal.getLabel(), literal.getDatatype());
			owned.add(copy);
			captures++;
			return copy;
		}
	}

	private static final class MutableLiteral extends SimpleLiteral {
		private static final long serialVersionUID = 1L;

		MutableLiteral(String label) {
			super(label);
		}

		void replaceLabel(String label) {
			setLabel(label);
		}
	}
